/// Copy for the About Us screen, in English and Malayalam.
///
/// Kept here rather than fetched from a database (unlike the app, which
/// reads this from its bundled sqlite) because the web build has no such
/// database, and this content changes rarely enough that a code review is
/// the right place to gate an edit.
class AboutInfo {
  AboutInfo._();

  static const String title = 'About Us';

  static const String titleMalayalam = 'ഞങ്ങളെക്കുറിച്ച്';

  static const String signedBy = 'D4DX INNOVATIONS LLP';

  /// The phrase within [description] that should read as a link to the
